use argh::FromArgs;
use tokio::runtime;

const MAX_CONN: usize = 1024;
const NUM_WORKERS: usize = 8;

#[derive(FromArgs)]
/// Sybil server.
struct Arguments {
    /// number of worker threads
    #[argh(option, short = 'w', default = "NUM_WORKERS")]
    workers: usize,
    /// maximum number of client connections
    #[argh(option, short = 'c', default = "MAX_CONN")]
    maxconn: usize,
    /// address to listen on
    #[argh(option, short = 'l')]
    listen: Option<String>,
}

async fn run(args: Arguments) -> Result<(), sybil::Error> {
    let server = sybil::new_server(args.listen, args.maxconn).await?;
    server.run().await;
    Ok(())
}

#[snafu::report]
fn main() -> Result<(), sybil::Error> {
    sybil::setup_logging()?;

    let main_args: Arguments = argh::from_env();

    runtime::Builder::new_multi_thread()
        .worker_threads(main_args.workers)
        .enable_all()
        .build()
        .unwrap()
        .block_on(run(main_args))
}

